<?php
if (!defined('ABSPATH')) exit;
function vitalis_setup(){
    add_theme_support('title-tag');
    add_theme_support('post-thumbnails');
    add_theme_support('html5',array('search-form','comment-form','gallery','caption','style','script'));
    add_theme_support('align-wide');
    add_theme_support('wp-block-styles');
    add_theme_support('responsive-embeds');
    add_theme_support('editor-styles');
    add_editor_style('assets/css/editor-content.css');
    register_nav_menus(array('primary'=>__('Ana Menü','vitalis')));
}
add_action('after_setup_theme','vitalis_setup');
function vitalis_assets(){wp_enqueue_style('vitalis-style',get_stylesheet_uri(),array(),'1.14.4');wp_enqueue_style('vitalis-main',get_template_directory_uri().'/assets/css/main.css',array('vitalis-style'),'1.14.4');wp_enqueue_style('vitalis-accessibility',get_template_directory_uri().'/assets/css/accessibility.css',array('vitalis-main'),'1.14.4');wp_enqueue_style('vitalis-targeted-fixes',get_template_directory_uri().'/assets/css/targeted-fixes.css',array('vitalis-accessibility'),'1.14.4');wp_enqueue_script('vitalis-main',get_template_directory_uri().'/assets/js/main.js',array(),'1.14.4',true);}
add_action('wp_enqueue_scripts','vitalis_assets');
function vitalis_img($n){return esc_url(get_template_directory_uri().'/assets/images/'.$n);}
function vitalis_make_pages(){if(get_option('vitalis_pages_created'))return;$pages=array('hakkimizda'=>'Hakkımızda','tesislerimiz'=>'Tesislerimiz','fitness-salonu'=>'Fitness Salonu','yuzme-havuzu'=>'Yüzme Havuzu','spor-sahalari'=>'Spor Sahaları','grup-dersleri'=>'Grup Dersleri','wellness'=>'Wellness Alanı','beslenme'=>'Beslenme Danışmanlığı','uyelik'=>'Üyelik','antrenorler'=>'Antrenörler','etkinlikler'=>'Etkinlikler','galeri'=>'Galeri','iletisim'=>'İletişim','rezervasyon'=>'Rezervasyon ve Kiralama');foreach($pages as $slug=>$title)if(!get_page_by_path($slug))wp_insert_post(array('post_title'=>$title,'post_name'=>$slug,'post_status'=>'publish','post_type'=>'page'));$id=wp_insert_post(array('post_title'=>'Ana Sayfa','post_name'=>'anasayfa','post_status'=>'publish','post_type'=>'page'));update_option('show_on_front','page');update_option('page_on_front',$id);update_option('vitalis_pages_created',1);}
add_action('after_switch_theme','vitalis_make_pages');
function vitalis_form_handler(){if(empty($_POST['vitalis_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['vitalis_nonce'])),'vitalis_form'))wp_die('Güvenlik doğrulaması başarısız.');$name=sanitize_text_field(wp_unslash($_POST['name']??''));$email=sanitize_email(wp_unslash($_POST['email']??''));$phone=sanitize_text_field(wp_unslash($_POST['phone']??''));$topic=sanitize_text_field(wp_unslash($_POST['topic']??'Genel bilgi'));$message=sanitize_textarea_field(wp_unslash($_POST['message']??''));if(!$name||!is_email($email)||!$message)wp_die('Lütfen ad, geçerli e-posta ve mesaj alanlarını doldurun.');$sent=wp_mail(get_option('admin_email'),'Vitalis web sitesi: '.$topic,"Ad Soyad: $name\nE-posta: $email\nTelefon: $phone\nKonu: $topic\n\n$message",array('Reply-To: '.$name.' <'.$email.'>'));wp_safe_redirect(add_query_arg('form',$sent?'sent':'error',wp_get_referer()?:home_url('/iletisim/')));exit;}
add_action('admin_post_nopriv_vitalis_contact','vitalis_form_handler');add_action('admin_post_vitalis_contact','vitalis_form_handler');
function vitalis_form(){
$prefill=isset($_GET['mesaj'])?sanitize_textarea_field(wp_unslash($_GET['mesaj'])):'';
$topic=isset($_GET['konu'])?sanitize_text_field(wp_unslash($_GET['konu'])):'';
if(isset($_GET['form']))echo '<p class="notice">'.(sanitize_key($_GET['form'])==='sent'?'Talebiniz gönderildi. En kısa sürede sizinle iletişime geçeceğiz.':'Gönderim başarısız. Lütfen telefonla ulaşın.').'</p>';?><form class="inquiry-form" method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="vitalis_contact"><?php wp_nonce_field('vitalis_form','vitalis_nonce');?><label>Ad Soyad<input name="name" required autocomplete="name"></label><label>E-posta<input type="email" name="email" required autocomplete="email"></label><label>Telefon<input type="tel" name="phone"></label><label>Konu<select name="topic"><option <?php selected($topic,'Üyelik başvurusu');?>>Üyelik başvurusu</option><option <?php selected($topic,'Tesis bilgisi');?>>Tesis bilgisi</option><option <?php selected($topic,'Saha kiralama');?>>Saha kiralama</option><option <?php selected($topic,'Grup dersi');?>>Grup dersi</option><option <?php selected($topic,'Antrenör ve seans ücretleri');?>>Antrenör ve seans ücretleri</option><option <?php selected($topic,'Etkinlik katılımı');?>>Etkinlik katılımı</option><option <?php selected($topic,'Genel bilgi');?>>Genel bilgi</option></select></label><label class="full">Mesajınız<textarea name="message" rows="5" required><?php echo esc_textarea($prefill);?></textarea></label><button class="btn" type="submit">Talep Gönder →</button><small>Talep WordPress yönetici e-posta adresine gönderilir. E-posta teslimi sunucu ayarlarına bağlıdır.</small></form><?php }
