if(!isset($d[$slug]))return '';list($title,$text,$photo,$items)=$d[$slug];ob_start();?><section class="page-hero" style="--page-image:url('<?php echo vitalis_img($photo);?>')"><div class="wrap"><span class="eyebrow">VITALIS SPORTS & WELLNESS CLUB</span><h1><?php echo esc_html($title);?></h1><p><?php echo esc_html($text);?></p><a class="btn" href="<?php echo esc_url(home_url('/iletisim/'));?>">Bilgi Al →</a></div></section><section class="wrap content-section"><div class="split"><div><span class="eyebrow">SİZİN İÇİN TASARLANDI</span><h2>İyi yaşam için ihtiyacınız olan her şey</h2><p>Uzman desteği, modern ekipman ve sizi motive eden bir topluluk. Vitalis’te ilk adımınızı bugün atın.</p><ul class="check-list"><?php foreach(explode('|',$items) as $it):?><li><?php echo esc_html($it);?></li><?php endforeach;?></ul></div><img class="feature-image" src="<?php echo vitalis_img($photo);?>" alt="<?php echo esc_attr($title);?>"></div><?php if(in_array($slug,array('iletisim','rezervasyon'))):?><div class="contact-grid"><div><h2><?php echo $slug==='rezervasyon'?'Genel bilgi talebi':'Bize ulaşın';?></h2><?php vitalis_form();?></div><aside class="contact-card"><h3>Vitalis Sports & Wellness Club</h3><p>Nilüfer, Bursa</p><p><a href="tel:+902241234567">0 (224) 123 45 67</a></p><p><a href="mailto:info@vitalisclub.com">info@vitalisclub.com</a></p><p>Pazartesi – Pazar<br>06.00 – 23.00</p><div class="contact-map"><iframe title="Vitalis Sports & Wellness Club — Nilüfer, Bursa haritası" src="https://maps.google.com/maps?q=Nil%C3%BCfer%2C%20Bursa&t=&z=13&ie=UTF8&iwloc=&output=embed" width="600" height="380" style="border:0" loading="lazy" referrerpolicy="no-referrer-when-downgrade" allowfullscreen></iframe></div><small>Harita Nilüfer, Bursa merkezini gösterir. Kesin tesis adresini gerçek konumla güncelleyin.</small></aside></div><?php endif;?></section><?php return ob_get_clean();}

